INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-5panel-guide-cap', 'The BankBeaters 5-Panel Guide Cap', 'the-bankbeaters-5-panel-guide-cap', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Waxed cotton 5-panel guide cap engineered with an unsinkable floatable EVA foam brim, dark glare-reducing underbill, and breathable brass ventilation eyelets.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'If your hat blows off in a river rapid, normal caps sink immediately. We built this with an EVA foam core brim that stays buoyant and recovers its shape after being stuffed into a pack for three days.', 'If your hat blows off in a river rapid, normal caps sink immediately. We built this with an EVA foam core brim that stays buoyant and recovers its shape after being stuffed into a pack for three days.', 'Dry-Finish Waxed Cotton Canvas, Floatable Closed-Cell EVA Foam Brim, Antiqued Brass Mesh Eyelets', '2.9 oz (82g)', 'Low Crown 5-Panel with Nylon Webbing Quick-Release Adjuster', 'Sewn and shaped in workshop', 44, 'active', 'cat-headwear', 'cat-headwear', 'gid://shopify/Product/106', '/media/the-bankbeaters-5-panel-guide-cap/hero.jpeg', '["/media/the-bankbeaters-5-panel-guide-cap/field-action.jpeg","/media/the-bankbeaters-5-panel-guide-cap/workbench-detail.jpeg","/media/the-bankbeaters-5-panel-guide-cap/bark-brown-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materials, weight=excluded.weight, fit_profile=excluded.fit_profile, origin=excluded.origin, base_price=excluded.base_price, status=excluded.status, category_id=excluded.category_id, category_id_id=excluded.category_id_id, shopify_product_id=excluded.shopify_product_id, featured_image=excluded.featured_image, gallery=excluded.gallery;
INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-bramble-buster-pant', 'Bramble-Buster Technical Guide Pant', 'bramble-buster-technical-guide-pant', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Heavyweight stretch ripstop guide pants fortified with 1000D Cordura scuff guards on knees and ankles. Built for scrambles up 60-degree dirt cuts and briar-choked access trails.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'Standard fishing waders get shredded by briars on the walk-in. These pants wear over thermal tights or wet-wading socks, taking the direct abuse from blackberry canes and sharp limestone riprap without puncturing.', 'Standard fishing waders get shredded by briars on the walk-in. These pants wear over thermal tights or wet-wading socks, taking the direct abuse from blackberry canes and sharp limestone riprap without puncturing.', 'Heavyweight 4-Way Stretch DWR Ripstop, 1000D Cordura® Knee & Ankle Panels, Mil-Spec Snap Closure', '17.8 oz (505g)', 'Technical Straight (Articulated knees, gusseted seat for steep cut-bank scrambles)', 'Hand-cut & sewn in small batches in Chris''s workshop', 215, 'active', 'cat-brush-pants', 'cat-brush-pants', 'gid://shopify/Product/102', '/media/bramble-buster-technical-guide-pant/hero.jpeg', '["/media/bramble-buster-technical-guide-pant/field-action.jpeg","/media/bramble-buster-technical-guide-pant/workbench-detail.jpeg","/media/bramble-buster-technical-guide-pant/camo-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materials, weight=excluded.weight, fit_profile=excluded.fit_profile, origin=excluded.origin, base_price=excluded.base_price, status=excluded.status, category_id=excluded.category_id, category_id_id=excluded.category_id_id, shopify_product_id=excluded.shopify_product_id, featured_image=excluded.featured_image, gallery=excluded.gallery;
INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-bushwhack-anorak', 'The Bushwhack Storm Anorak', 'bushwhack-storm-anorak', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Patagonia-grade 3-layer waterproof storm shell with 500D Cordura reinforced forearms and oversized kangaroo tackle pouch. Built to crawl through thorns, stay dry in torrential downpours, and cast all day.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'Designed for bushwhacking through dense alder thickets to find unpressured cutthroat runs. The 500D Cordura panels on the forearms take the beating so your membrane does not shred on thorny bank scrambles. Features two-way pit-to-hem venting zips.', 'Designed for bushwhacking through dense alder thickets to find unpressured cutthroat runs. The 500D Cordura panels on the forearms take the beating so your membrane does not shred on thorny bank scrambles. Features two-way pit-to-hem venting zips.', '3-Layer DWR Toray Ripstop (20,000mm/20,000g), 500D Cordura® Panels, YKK AquaGuard®', '21.4 oz (606g)', 'Relaxed Athletic (Engineered for layering and overhead casting mobility)', 'Hand-cut & sewn in small batches in Chris''s workshop', 340, 'active', 'cat-storm-shells', 'cat-storm-shells', 'gid://shopify/Product/101', '/media/bushwhack-storm-anorak/hero.jpeg', '["/media/bushwhack-storm-anorak/field-action.jpeg","/media/bushwhack-storm-anorak/workbench-detail.jpeg","/media/bushwhack-storm-anorak/camo-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materials, weight=excluded.weight, fit_profile=excluded.fit_profile, origin=excluded.origin, base_price=excluded.base_price, status=excluded.status, category_id=excluded.category_id, category_id_id=excluded.category_id_id, shopify_product_id=excluded.shopify_product_id, featured_image=excluded.featured_image, gallery=excluded.gallery;
INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-cutbank-sling-pack', 'The Cutbank Lumbar & Sling Convertible Pack', 'the-cutbank-lumbar-sling-pack', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Waterproof X-Pac composite sling that converts to a lumbar pack in seconds. Features an integrated magnetic net slot, Hypalon plier sheath with safety dock, and waterproof zipper compartments.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'When you are wading chest-deep or scrambling over downed timber, you need your pack out of your stroke until the second you land a fish. The Cutbank swings smoothly from lumbar to chest with one hand, featuring an integrated magnetic net dock.', 'When you are wading chest-deep or scrambling over downed timber, you need your pack out of your stroke until the second you land a fish. The Cutbank swings smoothly from lumbar to chest with one hand, featuring an integrated magnetic net dock.', 'Waterproof X-Pac® VX21 Composite Sailcloth, 500D Cordura® Base, YKK AquaGuard®, Hypalon Plier Dock', '14.2 oz (402g)', 'Ambidextrous Sling / Lumbar Switchable with Breathable 3D Spacer Mesh', 'Hand-crafted in Chris''s workshop', 195, 'active', 'cat-sling-packs', 'cat-sling-packs', 'gid://shopify/Product/103', '/media/the-cutbank-lumbar-sling-pack/hero.jpeg', '["/media/the-cutbank-lumbar-sling-pack/field-action.jpeg","/media/the-cutbank-lumbar-sling-pack/workbench-detail.jpeg","/media/the-cutbank-lumbar-sling-pack/coyote-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materials, weight=excluded.weight, fit_profile=excluded.fit_profile, origin=excluded.origin, base_price=excluded.base_price, status=excluded.status, category_id=excluded.category_id, category_id_id=excluded.category_id_id, shopify_product_id=excluded.shopify_product_id, featured_image=excluded.featured_image, gallery=excluded.gallery;
INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-minimalist-chest-rig', 'Minimalist Bank Chest Rig', 'minimalist-bank-chest-rig', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Ultralight modular chest station with fold-down tackle workbench shelf and interchangeable high-density EVA fly/lure patch. Straps cleanly over waders or breathable sun hoodies.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'Eliminates heavy vests. Rides high on your chest so you can wade to your armpits without soaking your terminal fly boxes. Fold-down front panel creates an instant workbench for knot-tying in heavy river current.', 'Eliminates heavy vests. Rides high on your chest so you can wade to your armpits without soaking your terminal fly boxes. Fold-down front panel creates an instant workbench for knot-tying in heavy river current.', '500D Mil-Spec Cordura®, High-Density Closed-Cell EVA Fly Patch, Duraflex® Mojave Buckles', '9.6 oz (272g)', 'Low-Profile 4-Point Harness (Rides high above deep wading lines)', 'Hand-crafted in Chris''s workshop', 135, 'active', 'cat-chest-rigs', 'cat-chest-rigs', 'gid://shopify/Product/104', '/media/minimalist-bank-chest-rig/hero.jpeg', '["/media/minimalist-bank-chest-rig/field-action.jpeg","/media/minimalist-bank-chest-rig/workbench-detail.jpeg","/media/minimalist-bank-chest-rig/prototype-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materials, weight=excluded.weight, fit_profile=excluded.fit_profile, origin=excluded.origin, base_price=excluded.base_price, status=excluded.status, category_id=excluded.category_id, category_id_id=excluded.category_id_id, shopify_product_id=excluded.shopify_product_id, featured_image=excluded.featured_image, gallery=excluded.gallery;
INSERT INTO products (id, title, slug, description, maker_field_notes, artist_statement, materials, weight, fit_profile, origin, base_price, status, category_id, category_id_id, shopify_product_id, featured_image, gallery) VALUES ('prod-waxed-tool-roll', 'Waxed Canvas & Cordura Tool Roll / Leader Wallet', 'waxed-canvas-cordura-tool-roll', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","children":[{"mode":"normal","text":"Heavyweight waxed canvas organizer with 6 internal slots for tippet spools, leader wallets, pliers, hook hones, and knot tools. Fastens securely with twin solid brass button snaps.","type":"text","style":"","detail":0,"format":0,"version":1}]}]}}', 'Built with Martexin waxed canvas that sheds river spray and weathers into a deep personal patina. Lined with blaze orange packcloth so terminal split-shot and micro-swivels never get lost in low dusk light.', 'Built with Martexin waxed canvas that sheds river spray and weathers into a deep personal patina. Lined with blaze orange packcloth so terminal split-shot and micro-swivels never get lost in low dusk light.', '12oz Martexin Original Waxed Canvas, 420D Hi-Vis Blaze Orange Packcloth, Solid Antiqued Brass Snaps', '6.5 oz (184g)', 'Tri-Fold Compact (Fits into any thigh pocket or pack exterior sleeve)', 'Hand-cut, waxed, and stitched with bonded nylon thread', 75, 'active', 'cat-tool-rolls', 'cat-tool-rolls', 'gid://shopify/Product/105', '/media/waxed-canvas-cordura-tool-roll/hero.jpeg', '["/media/waxed-canvas-cordura-tool-roll/field-action.jpeg","/media/waxed-canvas-cordura-tool-roll/workbench-detail.jpeg","/media/waxed-canvas-cordura-tool-roll/charcoal-variation.jpeg"]') ON CONFLICT(id) DO UPDATE SET title=excluded.title, slug=excluded.slug, description=excluded.description, maker_field_notes=excluded.maker_field_notes, artist_statement=excluded.artist_statement, materials=excluded.materi